import numpy as np
from scipy.linalg import cho_solve, cho_factor
rng=np.random.default_rng(2024)
K=32; k=np.arange(1,K+1,dtype=float); xg=np.arange(1,257)/257; xo=np.arange(1,129)/129
def make(pt):
    z=rng.standard_normal(K); c=z*k**(-pt); c/=np.sqrt(.5*np.sum(c*c)); return c
def obs(c,kap,times,sig,nper):
    rows=[]
    for t in times:
        idx=rng.choice(128,nper,replace=False); x=xo[idx]
        A=np.exp(-kap*np.pi**2*k[None,:]**2*t)*np.sin(np.pi*x[:,None]*k[None,:])
        rows.append((x,t,A@c+sig*rng.standard_normal(nper)))
    return (np.concatenate([r[0] for r in rows]),np.concatenate([np.full(len(r[0]),r[1]) for r in rows]),
            np.concatenate([r[2] for r in rows]))
def post(A,y,sig,p,scale=1.,ret_ev=False):
    v=k**(-2*p); v=v/(.5*v.sum())*scale
    B=A.T@A/sig**2+np.diag(1/v); cf=cho_factor(B,lower=True)
    co=cho_solve(cf,A.T@y/sig**2)
    if not ret_ev: return co
    AtA=A.T@A; Aty=A.T@y
    ld=len(y)*np.log(sig**2)+np.sum(np.log(v))+2*np.sum(np.log(np.diag(cf[0])))
    q=y@y/sig**2-(Aty@cho_solve(cf,Aty))/sig**4
    return co,-.5*(ld+q)
def estimate(A,y,sig,mode):
    if mode=='fixed': co=post(A,y,sig,2.0)
    else:
        ps=np.linspace(1.0,3.0,21); best=None
        for p in ps:
            co,ev=post(A,y,sig,p,ret_ev=True)
            if best is None or ev>best[0]: best=(ev,co,p)
        co=best[1]
    return co
def err(c,co,kap,tf):
    ut=np.sin(np.pi*xg[:,None]*k[None,:])@c
    uft=np.sin(np.pi*xg[:,None]*k[None,:])@(c*np.exp(-kap*np.pi**2*k**2*tf))
    u=np.sin(np.pi*xg[:,None]*k[None,:])@co
    uf=np.sin(np.pi*xg[:,None]*k[None,:])@(co*np.exp(-kap*np.pi**2*k**2*tf))
    return np.linalg.norm(u-ut)/np.linalg.norm(ut), np.linalg.norm(uf-uft)/np.linalg.norm(uft)
levels=[(.001,.004,.005,.005),(.003,.009,.01125,.009),(.006,.018,.0225,.017)]
for nper,sigscale in [(64,1),(96,1),(64,1.5),(64,2)]:
    print('\nSTRESS n',nper,'sigx',sigscale)
    for mode in ['fixed','select']:
        vals=[]
        for li,(t1,t2,tf,s0) in enumerate(levels):
            for rep in range(40):
                c=make(2.0); kap=rng.uniform(.5,1.5); sig=s0*sigscale*(.7+.6*rng.random())
                x,t,y=obs(c,kap,[t1,t2],sig,nper)
                A=np.exp(-kap*np.pi**2*k[None,:]**2*t[:,None])*np.sin(np.pi*x[:,None]*k[None,:])
                co=estimate(A,y,sig,mode); vals.append((*err(c,co,kap,tf),li))
        v=np.array(vals); fails=((v[:,0]>.15)|(v[:,1]>.03)).sum()
        print(mode,'Emean %.3f Emax %.3f EFmax %.4f fails %d/%d'%(v[:,0].mean(),v[:,0].max(),v[:,1].max(),fails,len(v)))
